import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        LuckyTickets solver = new LuckyTickets();
        solver.solve(1, in, out);
        out.close();
    }

    static class LuckyTickets {
        int MOD = 998244353;
        static long mask = (1L << 31) - 1;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int k = in.nextInt();
            long[] dig = new long[11];
            for (int i = 0; i < k; i++) {
                dig[10 - in.nextInt()] = 1;
            }
            int power = N / 2;
            long[] res = new long[1];
            res[0] = 1;
            while (power > 0) {
                if (((power & 1) > 0)) {
                    res = convoluteSimply(res.clone(), dig.clone(), MOD, 3);
                }
                dig = convoluteSimply(dig.clone(), dig.clone(), MOD, 3);
                power >>= 1;
            }
            long output = 0;
            for (int i = 0; i < res.length; i++) {
                output += res[i] * res[i];
                output %= 998244353;
            }
            out.println(output);
        }

        public static long[] convoluteSimply(long[] a, long[] b, int P, int g) {
            int m = Math.max(2, Integer.highestOneBit(Math.max(a.length, b.length) - 1) << 2);
            long[] fa = nttmb(a, m, false, P, g);
            long[] fb = a == b ? fa : nttmb(b, m, false, P, g);
            for (int i = 0; i < m; i++) {
                fa[i] = fa[i] * fb[i] % P;
            }
            return nttmb(fa, m, true, P, g);
        }

        private static long[] nttmb(long[] src, int n, boolean inverse, int P, int g) {
            long[] dst = Arrays.copyOf(src, n);

            int h = Integer.numberOfTrailingZeros(n);
            long K = Integer.highestOneBit(P) << 1;
            int H = Long.numberOfTrailingZeros(K) * 2;
            long M = K * K / P;

            int[] wws = new int[1 << h - 1];
            long dw = inverse ? pow(g, P - 1 - (P - 1) / n, P) : pow(g, (P - 1) / n, P);
            long w = (1L << 32) % P;
            for (int k = 0; k < 1 << h - 1; k++) {
                wws[k] = (int) w;
                w = modh(w * dw, M, H, P);
            }
            long J = invl(P, 1L << 32);
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < 1 << i; j++) {
                    for (int k = 0, s = j << h - i, t = s | 1 << h - i - 1; k < 1 << h - i - 1; k++, s++, t++) {
                        long u = (dst[s] - dst[t] + 2 * P) * wws[k];
                        dst[s] += dst[t];
                        if (dst[s] >= 2 * P) dst[s] -= 2 * P;
//					long Q = (u&(1L<<32)-1)*J&(1L<<32)-1;
                        long Q = (u << 32) * J >>> 32;
                        dst[t] = (u >>> 32) - (Q * P >>> 32) + P;
                    }
                }
                if (i < h - 1) {
                    for (int k = 0; k < 1 << h - i - 2; k++) wws[k] = wws[k * 2];
                }
            }
            for (int i = 0; i < n; i++) {
                if (dst[i] >= P) dst[i] -= P;
            }
            for (int i = 0; i < n; i++) {
                int rev = Integer.reverse(i) >>> -h;
                if (i < rev) {
                    long d = dst[i];
                    dst[i] = dst[rev];
                    dst[rev] = d;
                }
            }

            if (inverse) {
                long in = invl(n, P);
                for (int i = 0; i < n; i++) dst[i] = modh(dst[i] * in, M, H, P);
            }

            return dst;
        }

        public static long modh(long a, long M, int h, int mod) {
            long r = a - ((M * (a & mask) >>> 31) + M * (a >>> 31) >>> h - 31) * mod;
            return r < mod ? r : r - mod;
        }

        private static long pow(long a, long n, long mod) {
            //		a %= mod;
            long ret = 1;
            int x = 63 - Long.numberOfLeadingZeros(n);
            for (; x >= 0; x--) {
                ret = ret * ret % mod;
                if (n << 63 - x < 0)
                    ret = ret * a % mod;
            }
            return ret;
        }

        private static long invl(long a, long mod) {
            long b = mod;
            long p = 1, q = 0;
            while (b > 0) {
                long c = a / b;
                long d;
                d = a;
                a = b;
                b = d % b;
                d = p;
                p = q;
                q = d - c * q;
            }
            return p < 0 ? p + mod : p;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}


